import{c as i,J as o,h as r,k as t}from"./chunks/framework.NhpCCunm.js";const p=JSON.parse('{"title":"Витрина и интернет-магазин","description":"Встроенный генератор статического интернет-магазина (Jamstack SSG), единый стол заказов и транспорт публикации в ОмниКрафт ЕРП.","frontmatter":{"title":"Витрина и интернет-магазин","description":"Встроенный генератор статического интернет-магазина (Jamstack SSG), единый стол заказов и транспорт публикации в ОмниКрафт ЕРП.","order":9},"headers":[],"relativePath":"ru/docs/spaces/production/web-store.md","filePath":"ru/docs/spaces/production/web-store.md"}'),a={name:"ru/docs/spaces/production/web-store.md"};function s(e,l,n,g,h,d){return o(),r("div",null,[...l[0]||(l[0]=[t('<h1 id="витрина-и-интернет-магазин-мастера" tabindex="-1">Витрина и интернет-магазин мастера <a class="header-anchor" href="#витрина-и-интернет-магазин-мастера" aria-label="Permalink to &quot;Витрина и интернет-магазин мастера&quot;">​</a></h1><p>Встроенный модуль <strong>«Витрина и интернет-магазин»</strong> позволяет ремесленнику в один клик превратить базу изделий и технологических карт в автономный, быстрый и современный статический сайт-каталог без ежемесячной абонентской платы за конструкторы сайтов.</p><p>Витрина компилируется как статический сайт: на выходе получается чистая верстка без уязвимых серверных движков. Каталог открывается мгновенно на любых устройствах и может бесплатно размещаться на облачных дисках или на собственном сервере.</p><hr><h2 id="архитектура-и-возможности" tabindex="-1">Архитектура и возможности <a class="header-anchor" href="#архитектура-и-возможности" aria-label="Permalink to &quot;Архитектура и возможности&quot;">​</a></h2><p>Модуль объединяет четыре ключевые подсистемы:</p><ol><li><p><strong>Единый стол заказов (Входящие заявки):</strong></p><ul><li>Централизованный сбор заказов с сайта, Авито, мессенджеров и маркетплейсов.</li><li>Умная вставка из буфера обмена: автоматическое распознавание имени клиента, телефона, адреса доставки и состава заказа из текста переписки.</li><li>Быстрые ответы клиентам: готовые шаблоны сообщений («Заказ подтвержден», «Готово к отправке», «Реквизиты для оплаты») с автоматической подстановкой данных и прямой отправкой в мессенджеры.</li><li>Проведение продажи в один клик: автоматическое списание готовой продукции по правилу ФИФО и создание записи в журнале продаж.</li></ul></li><li><p><strong>Каталог товаров на витрине:</strong></p><ul><li>Управление видимостью изделий на сайте одним переключателем.</li><li>Привлекательные бейджи («Хит», «Новинка», «Под заказ», «В наличии»).</li><li>Независимая цена для сайта (при необходимости отличающаяся от базовой розничной цены).</li><li>Описание в текстовом формате и фотогалерея.</li></ul></li><li><p><strong>Профиль и оформление витрины:</strong></p><ul><li>Название мастерской, слоган, история мастера и условия доставки.</li><li>Прямые контакты (телефон, мессенджеры, электронная почта).</li><li>Интеграция с Яндекс.Формами для удобного приема заявок без программирования.</li></ul></li><li><p><strong>Универсальный транспорт публикации:</strong></p><ul><li><strong>Локальная папка / архив:</strong> сохранение готового сайта на компьютер для передачи верстальщику или ручной загрузки.</li><li><strong>Сетевой протокол передачи (FTP):</strong> прямая публикация на любой хостинг с инкрементальной проверкой по контрольным суммам (не перезаливает неизменившиеся фотографии).</li><li><strong>Облачные хранилища (S3):</strong> Яндекс Облако и другие совместимые провайдеры.</li><li><strong>Публикация на ГитХаб:</strong> автоматическая публикация через официальный интерфейс.</li><li>Аппаратное шифрование паролей и ключей доступа через криптографический сейф.</li></ul></li></ol><hr><h2 id="пошаговое-руководство" tabindex="-1">Пошаговое руководство <a class="header-anchor" href="#пошаговое-руководство" aria-label="Permalink to &quot;Пошаговое руководство&quot;">​</a></h2><h3 id="шаг-1-подготовка-товаров-к-публикации" tabindex="-1">Шаг 1. Подготовка товаров к публикации <a class="header-anchor" href="#шаг-1-подготовка-товаров-к-публикации" aria-label="Permalink to &quot;Шаг 1. Подготовка товаров к публикации&quot;">​</a></h3><ol><li>Перейдите во вкладку <strong>«Витрина»</strong> → подвкладка <strong>«Товары на витрине»</strong> (или откройте карточку рецепта в <strong>Калькуляторе</strong> на вкладке «Витрина»).</li><li>Включите тумблер <strong>«Опубликовать»</strong> напротив нужных изделий.</li><li>Нажмите кнопку настройки (иконка ползунков), чтобы задать URL-псевдоним (slug), бейдж и привлекательное описание.</li></ol><h3 id="шаг-2-заполнение-информации-о-мастерскои" tabindex="-1">Шаг 2. Заполнение информации о мастерской <a class="header-anchor" href="#шаг-2-заполнение-информации-о-мастерскои" aria-label="Permalink to &quot;Шаг 2. Заполнение информации о мастерской&quot;">​</a></h3><ol><li>Откройте подвкладку <strong>«Профиль и стиль»</strong>.</li><li>Укажите название вашей мастерской, слоган и город.</li><li>Добавьте контакты для связи в мессенджерах и блок с описанием условий доставки и оплаты.</li><li>Нажмите кнопку <strong>«Сохранить профиль»</strong>.</li></ol><h3 id="шаг-3-настроика-транспорта-и-публикация" tabindex="-1">Шаг 3. Настройка транспорта и публикация <a class="header-anchor" href="#шаг-3-настроика-транспорта-и-публикация" aria-label="Permalink to &quot;Шаг 3. Настройка транспорта и публикация&quot;">​</a></h3><ol><li>Откройте подвкладку <strong>«Транспорт публикации»</strong>.</li><li>Выберите подходящий способ размещения (например, <em>Локальная папка</em> для проверки или <em>GitHub Pages</em> / <em>FTP</em> для рабочего сайта).</li><li>Введите параметры доступа и нажмите <strong>«Проверить подключение»</strong>.</li><li>После успешного теста нажмите <strong>«Сохранить транспорт»</strong>.</li><li>В верхней панели витрины нажмите кнопку <strong>«Опубликовать сайт»</strong>.</li></ol><p>Программа скомпилирует витрину, оптимизирует изображения, соберет корзину заказов и выгрузит готовый сайт на выбранный хостинг.</p><hr><h2 id="работа-со-столом-заказов" tabindex="-1">Работа со столом заказов <a class="header-anchor" href="#работа-со-столом-заказов" aria-label="Permalink to &quot;Работа со столом заказов&quot;">​</a></h2><p>Когда клиент оформляет заказ на сайте или пишет вам в чате Авито:</p><ol><li>Откройте вкладку <strong>«Стол заказов»</strong>.</li><li>Если клиент написал в мессенджере, скопируйте текст сообщения и нажмите <strong>«Умная вставка»</strong>. Программа сама заполнит контакты и состав заказа.</li><li>Для ответа клиенту нажмите кнопку <strong>«Ответить»</strong>: выберите готовый шаблон и перейдите в чат в один клик.</li><li>Когда изделие готово и отправлено, нажмите <strong>«Провести продажу»</strong>: программа автоматически спишет партии по ФИФО и зафиксирует доход.</li></ol>',20)])])}const u=i(a,[["render",s]]);export{p as __pageData,u as default};
